import './Layout.css'
import type { HTMLAttributes } from 'react'
import { cn } from '../lib/cn'

type Gap = 1 | 2 | 3 | 4 | 6 | 8 | 12 | 16
type Span = 3 | 4 | 6 | 8 | 9 | 12

type Props = HTMLAttributes<HTMLDivElement> & {
  /** Space between the tracks, as a step of the 4pt scale — spacing lives on the
   *  container, never as margins on the children. The scale is the whole point:
   *  a number that is not a step is a decision nobody made. */
  gap?: Gap
  /**
   * Twelve equal tracks instead of the auto-fitting default: the layout where
   * items are DIFFERENT sizes (a wide feature beside two narrow tiles), each
   * child wrapped in `GridItem` with its `span`. Omit it and every child gets
   * the same width, which is the right answer for a set of equals.
   */
  /* `columnCount`, not `columns`: the word means the column DEFINITIONS on the
   * four parts that publish a list of them. (2026-09-03) */
  columnCount?: 12
  /**
   * The narrowest a card in this grid may get before the grid drops a column.
   * `sm` (16rem) is the default and right for tiles that carry a word or two;
   * `md` (20rem) is what a card with a name, a role and an action needs; `lg`
   * (24rem) is for a card with a picture and two sentences. Measured, not
   * guessed: at `sm` a person card came out 250px wide on a laptop and every
   * name broke over two lines.
   */
  /* `minColumn`, not `min`: `min` everywhere else in this system is the smallest
   * value a control accepts, a date or a number. This is how narrow a column may
   * get before the grid drops one. (2026-09-03) */
  minColumn?: 'sm' | 'md' | 'lg'
  /**
   * How the children sit in their row. The default stretches them to the
   * tallest, and for CARDS that default is the rule: cards in a row are always
   * the same height (owner, 23.08). A ragged row is answered by giving the
   * short card the part it is missing, never by `start`. Use these values for a
   * grid of things that are not cards — captions, thumbnails, controls — where
   * a row of unequal boxes is what was asked for.
   */
  align?: 'start' | 'center' | 'end'
  /* Every card in a row sits on the SAME row tracks (CSS subgrid), so a long
   * title in one card no longer pushes its neighbour's excerpt and meta out of
   * line. Only <ContentCard> knows how to take part; other children are
   * unaffected. */
  /** Makes every row as tall as its tallest item, so cards in a grid line up
   *  across rows instead of each row setting its own height. Leave it off when
   *  the items are meant to be their own size. */
  alignRows?: boolean
}

/**
 * Layout primitives: Stack and Row for gaps in one direction, Grid for a set of
 * cards — auto-fitting equals by default, or `columnCount={12}` with `GridItem`
 * spans when the set is deliberately unequal. `gap` is a token step, never a
 * raw px.
 */
export function Grid({ gap = 4, columnCount, minColumn, align, alignRows, className, ...rest }: Props) {
  return (
    <div
      className={cn('grid', className)}
      data-gap={gap}
      data-column-count={columnCount}
      data-min-column={minColumn}
      data-align={align}
      data-align-rows={alignRows || undefined}
      {...rest}
    />
  )
}

type ItemProps = HTMLAttributes<HTMLDivElement> & {
  /** Tracks of the twelve this item occupies: 3 = a quarter, 6 = a half, 12 = the row. */
  span?: Span
}

/**
 * One cell of a `columnCount={12}` Grid. Below the tablet breakpoint the twelve
 * tracks become six and every span rounds to a half or the full row; below the
 * phone breakpoint there is one column and spans stop meaning anything — a
 * quarter-width card is unreadable at 390px, and no span is worth that.
 */
export function GridItem({ span = 12, className, ...rest }: ItemProps) {
  return <div className={cn('grid-item', className)} data-span={span} {...rest} />
}

/* Layout primitives — Stack (column), Row (horizontal), Grid (auto-fit) */
.stack { display: flex; flex-direction: column; }
.row   { display: flex; flex-direction: row; flex-wrap: wrap; align-items: center; }
.row[data-nowrap] { flex-wrap: nowrap; }
.grid  { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--min-item, 16rem)), 1fr)); }
/* How narrow a card in this grid may get before the grid drops a column. The
 * auto-fit default packs at 16rem, which is right for a tile that carries two
 * words and wrong for a card that carries a name, a role and an action: at 16rem
 * a person card measured 250px on a laptop and every name broke over two lines
 * (owner, 22.08). `min(100%, …)` keeps the track from overflowing a container
 * narrower than the minimum itself. */
/* CARDS IN A ROW ARE THE SAME HEIGHT (owner's rule, 23.08), which is the grid's
 * own default — these values are the escape hatch for a grid of things that are
 * NOT cards. The ragged-row problem they used to solve is a content problem: a
 * card that runs short is missing a part, and CardMeta pinning to the foot puts
 * the spare height where it reads as air rather than as a hole. */
.grid[data-align="start"]  { align-items: start; }
.grid[data-align="center"] { align-items: center; }
.grid[data-align="end"]    { align-items: end; }

.grid[data-min-column="sm"] { --min-item: 16rem; }
.grid[data-min-column="md"] { --min-item: 20rem; }
.grid[data-min-column="lg"] { --min-item: 24rem; }

/* The unequal set: twelve tracks, each item declaring how many it takes. The
 * auto-fit default above answers "a set of equals"; this answers "a wide one
 * beside two narrow ones", which no minmax can express. */
.grid[data-column-count="12"] { grid-template-columns: repeat(12, minmax(0, 1fr)); }
.grid-item[data-span="3"]  { grid-column: span 3; }
.grid-item[data-span="4"]  { grid-column: span 4; }
.grid-item[data-span="6"]  { grid-column: span 6; }
.grid-item[data-span="8"]  { grid-column: span 8; }
.grid-item[data-span="9"]  { grid-column: span 9; }
.grid-item[data-span="12"] { grid-column: span 12; }
/* A GridItem is a cell, not a box. The cell stretches to the row and now passes
 * that on: its content used to stop at its own text while the cell around it ran
 * to the bottom of the row, so a twelve-column set came out ragged while an
 * auto-fit set did not — same rule, two answers. */
.grid-item { display: flex; flex-direction: column; min-inline-size: 0; }
.grid-item > * { flex: 1 1 auto; }

/* Below the tablet edge twelve tracks become six: a quarter would be 170px of
 * card, which is narrower than the words in it. Everything wider than a half
 * takes the whole row. */
/* The twelve tracks answer the GRID's own width, not the window's.
 *
 * Measured 22.08: at an 800px viewport this page's content column is ~500px, so
 * a `span 4` card came out 148px wide, and the nested grid inside a card gave
 * SIX columns of 65px. The viewport was 800 and the old media query fired at
 * 768, so nothing caught it: the window was wide, the grid was not.
 *
 * The track count stays twelve at every width and only the SPANS change. That
 * is not a stylistic choice: `@container` styles the container's DESCENDANTS,
 * never the container itself, so a grid cannot use its own width to change its
 * own `grid-template-columns` — measured the hard way, with six tracks left at
 * twelve and the items collapsed to one, which is how a person card ended up
 * 65px wide. The items are descendants; they can be told. */
.grid[data-column-count="12"] { container-type: inline-size; }

/* Under 48rem of GRID: a quarter or a third becomes a half, a half or more
 * becomes the whole row. */
@container (max-width: 48rem) {
  .grid-item[data-span="3"],
  .grid-item[data-span="4"]  { grid-column: span 6; }
  .grid-item[data-span="6"],
  .grid-item[data-span="8"],
  .grid-item[data-span="9"]  { grid-column: span 12; }
}

/* Under 30rem: one card per row. Two 15rem cards side by side is two cards
 * neither of which can carry a name and a role. */
@container (max-width: 30rem) {
  .grid-item[data-span] { grid-column: span 12; }
}

.stack[data-gap="1"],  .row[data-gap="1"],  .grid[data-gap="1"]  { gap: var(--space-1); }
.stack[data-gap="2"],  .row[data-gap="2"],  .grid[data-gap="2"]  { gap: var(--space-2); }
.stack[data-gap="3"],  .row[data-gap="3"],  .grid[data-gap="3"]  { gap: var(--space-3); }
.stack[data-gap="4"],  .row[data-gap="4"],  .grid[data-gap="4"]  { gap: var(--space-4); }
.stack[data-gap="6"],  .row[data-gap="6"],  .grid[data-gap="6"]  { gap: var(--space-6); }
.stack[data-gap="8"],  .row[data-gap="8"],  .grid[data-gap="8"]  { gap: var(--space-8); }
.stack[data-gap="12"], .row[data-gap="12"], .grid[data-gap="12"] { gap: var(--space-12); }
.stack[data-gap="16"], .row[data-gap="16"], .grid[data-gap="16"] { gap: var(--space-16); }

.row[data-align="start"]     { align-items: flex-start; }
.row[data-align="center"]    { align-items: center; }
.row[data-align="end"]       { align-items: flex-end; }
/* A row that fills its flex parent's main axis. `justify` can only place
 * content INSIDE the row's own width, so a row sized by its contents has
 * nothing to centre against: a centred action group inside <CardMeta> (which
 * spreads its children) sat at the start of the footer until the row could
 * grow. */
.row[data-grow] { flex: 1; }
.row[data-justify="between"] { justify-content: space-between; }
.row[data-justify="center"] { justify-content: center; }
.row[data-justify="end"] { justify-content: flex-end; }

import './Layout.css'
import type { HTMLAttributes } from 'react'
import { cn } from '../lib/cn'

type Gap = 1 | 2 | 3 | 4 | 6 | 8 | 12 | 16

type Props = HTMLAttributes<HTMLDivElement> & {
  /** Space between the children, as a step of the 4pt scale. On the container,
   *  never as margins on the children: margins collapse and double, a gap does
   *  neither. */
  gap?: Gap
  align?: 'start' | 'center' | 'end'
  /** Where the row's content sits on the main axis. `center` is the one action
   *  under a card's content; `end` is a toolbar's trailing edge. Added 2026-08-22:
   *  the row could only spread, so every screen that needed a centred control
   *  wrote its own class for it. */
  justify?: 'between' | 'center' | 'end'
  /**
   * Keeps the row on ONE line. A row wraps by default, which is right for a
   * group of controls and wrong for a pair that means one thing — a mark beside
   * a label, a figure beside its unit. Without it the mark dropped onto a line
   * of its own the moment the words needed the space, so the same tile showed
   * the icon beside the title in a wide card and above it in a narrow one
   * (owner, 2026-08-25).
   *
   * The item that must give way needs a floor of zero; that is the caller's,
   * because only the caller knows which of the two it is.
   */
  nowrap?: boolean
  /** Takes the whole main axis of the flex parent it sits in. Without it a Row
   *  is only as wide as its contents, so `justify="center"` centres them inside
   *  that width and the group still sits wherever the parent put it — which is
   *  how a centred action row under a portrait ended up left-aligned inside
   *  <CardMeta> (owner, 23.08). */
  grow?: boolean
}

export function Row({ gap = 3, align, justify, grow, nowrap, className, ...rest }: Props) {
  return (
    <div
      className={cn('row', className)}
      data-gap={gap}
      data-align={align}
      data-justify={justify}
      data-grow={grow || undefined}
      data-nowrap={nowrap || undefined}
      {...rest}
    />
  )
}

import './Layout.css'
import type { HTMLAttributes } from 'react'
import { cn } from '../lib/cn'

type Gap = 1 | 2 | 3 | 4 | 6 | 8 | 12 | 16

type Props = HTMLAttributes<HTMLElement> & {
  /** Space between the children, as a step of the 4pt scale. On the container,
   *  never as margins on the children: margins collapse and double, a gap does
   *  neither. */
  gap?: Gap
  /**
   * The element this renders as, when the DOCUMENT has an opinion the layout
   * does not: a stack of list items is a list, and a screen reader that is
   * handed a column of divs is told there are no items and no count. Added
   * 2026-08-23, when the system's own site had a list of rules and could not
   * say so in a Stack.
   */
  as?: 'div' | 'ul' | 'ol' | 'section' | 'nav'
}

export function Stack({ gap = 4, as: As = 'div', className, ...rest }: Props) {
  return (
    <As
      className={cn('stack', className)}
      data-gap={gap}
      {...rest}
    />
  )
}
